    const angle = (i * Math.PI / 3) - Math.PI/6;
    const x1 = 200 + Math.cos(angle) * 100;
    const y1 = 200 + Math.sin(angle) * 100;
    const x2 = 200 + Math.cos(angle + Math.PI/3) * 100;
    const y2 = 200 + Math.sin(angle + Math.PI/3) * 100;
    const x3 = 200 + Math.cos(angle - Math.PI/3) * 100;
    const y3 = 200 + Math.sin(angle - Math.PI/3) * 100;

    ctx.beginPath();
    ctx.moveTo(200, 200);
    ctx.lineTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.closePath();
    ctx.fill();
}

